UPDATE capability_mutation_record
SET execution_token = #{executionToken}, lease_until = #{leaseUntil}, updated_at = CURRENT_TIMESTAMP
WHERE run_id = #{runId} AND call_id = #{callId}
  AND request_fingerprint = #{fingerprint}
  AND status IN (0, 3)
  AND (lease_until IS NULL OR lease_until <= #{now})
